#!/usr/bin/env bash
set -euo pipefail
# Live: runs Observe against this instance's live memory. Opt in with EGREGORE_LIVE_INTEGRATION=1; otherwise report a skip.
if [ "${EGREGORE_LIVE_INTEGRATION:-}" != 1 ]; then echo "SKIP: runs Observe against this instance's live memory; set EGREGORE_LIVE_INTEGRATION=1 to run"; exit 0; fi

# Test: normal Claude/Codex recall prompts enter EgregoreRuntime.observe.
# Generated by /qa on 2026-08-26 for egregore-runtime-architecture.
# Covers: prompt hooks -> harness CLI -> Runtime Observe -> Retriever boundary.

ROOT="$(cd "$(dirname "$0")/../.." && pwd)"
PASS=0
FAIL=0

pass() { PASS=$((PASS + 1)); echo "  ✓ $1"; }
fail() { FAIL=$((FAIL + 1)); echo "  ✗ $1"; [ -n "${2:-}" ] && echo "    $2"; }

echo "Testing: harness prompt → Observe integration"
echo ""

if jq -e '.hooks.UserPromptSubmit[].hooks[].command | select(contains("bin/observe-context.sh claude"))' \
  "$ROOT/.claude/settings.json" >/dev/null; then
  pass "Claude UserPromptSubmit compiles organizational context"
else
  fail "Claude hook does not enter the Observe adapter"
fi

if jq -e '.hooks.UserPromptSubmit[].hooks[].command | select(contains("bin/observe-context.sh") and contains("codex"))' \
  "$ROOT/.codex/hooks.json" >/dev/null; then
  pass "Codex UserPromptSubmit compiles organizational context"
else
  fail "Codex hook does not enter the Observe adapter"
fi

if grep -Fq 'python3 -m egregore_runtime.harness_cli prompt-hook' "$ROOT/bin/observe-context.sh"; then
  pass "prompt hooks use the harness-neutral Runtime adapter"
else
  fail "prompt hook bypasses the harness-neutral Runtime adapter"
fi

legacy_payload='{"prompt":"What did we decide about graph retrieval in the Local architecture?"}'
legacy_codex_output=$(printf '%s\n' "$legacy_payload" | node "$ROOT/.codex/hooks/search-hint.js")
if grep -Fq 'EGREGORE_ORG_CONTEXT_V1' <<< "$legacy_codex_output" && \
   ! grep -Fq 'Routing hint:' <<< "$legacy_codex_output"; then
  pass "Codex linked-worktree compatibility hook enters Observe"
else
  fail "Codex linked-worktree compatibility hook did not enter Observe"
fi

legacy_claude_output=$(printf '%s\n' "$legacy_payload" | EGREGORE_ROOT="$ROOT" bash "$ROOT/.claude/hooks/search-hint.sh")
if grep -Fq 'EGREGORE_ORG_CONTEXT_V1' <<< "$legacy_claude_output" && \
   ! grep -Fq 'Routing hint:' <<< "$legacy_claude_output"; then
  pass "Claude linked-worktree compatibility hook enters Observe"
else
  fail "Claude linked-worktree compatibility hook did not enter Observe"
fi

query_block=$(sed -n '/^_runtime()/,/^}/p' "$ROOT/bin/search.sh")
if grep -Fq 'egregore_runtime.harness_cli' <<< "$query_block" && \
   ! grep -Fqi 'qmd' <<< "$query_block"; then
  pass "normal search traffic has no QMD-specific dependency"
else
  fail "normal search traffic still enters a QMD-specific CLI"
fi

if command -v pytest >/dev/null 2>&1; then
  test_command=(pytest -q "$ROOT/tests/test_harness_observe.py")
else
  test_command=(python3 -m pytest -q "$ROOT/tests/test_harness_observe.py")
fi
if PYTHONPATH="$ROOT" "${test_command[@]}"; then
  pass "dynamic prompt and query calls reach Runtime.observe"
else
  fail "dynamic Observe integration tests failed"
fi

for harness in codex pi prime; do
  bundle="$ROOT/packages/create-egregore/runtime/$harness"
  if grep -Fq 'egregore_runtime.harness_cli' "$bundle/bin/search.sh" && \
     grep -Fq 'bin/observe-context.sh' "$bundle/manifest.json" && \
     grep -Fq 'egregore_runtime/harness_cli.py' "$bundle/manifest.json"; then
    pass "$harness package carries the harness-to-Observe adapter"
  else
    fail "$harness package lost the harness-to-Observe adapter"
  fi
done

echo ""
echo "$PASS passed, $FAIL failed"
[ "$FAIL" -gt 0 ] && exit 1 || exit 0
